code = bytes.fromhex("90 90 CC C3")
names = {0x90: "nop", 0xC3: "ret", 0xCC: "int3"}
for address, byte in enumerate(code):
    print(address, format(byte, "02X"), names[byte])

names = ["EAX", "ECX", "EDX", "EBX", "ESP", "EBP", "ESI", "EDI"]
for number, name in enumerate(names):
    print(number, name)
